--
-- Name: mv_attendance_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: attenda
--

CREATE MATERIALIZED VIEW public.mv_attendance_summary AS
 SELECT date("timestamp") AS attendance_date,
    dept,
    count(*) AS total_attendance,
    count(DISTINCT reg_no) AS unique_users
   FROM public.attendance
  WHERE ("timestamp" >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY (date("timestamp")), dept
  ORDER BY (date("timestamp")) DESC, dept
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_attendance_summary OWNER TO attenda;

